-- Tema 1: Elementos básicos de línea y ángulo
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Elementos básicos de línea y ángulo', 10, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 1.1: Punto, recta, segmento, rayo y plano
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Punto, recta, segmento, rayo y plano', 'Por un punto A pueden pasar **muchas rectas**, pero por dos puntos A y B pasa **una sola recta**.\n\n| Elemento | Qué es | Símbolo |\n|---|---|---|\n| **Recta AB** | Línea que pasa por A y B y se extiende sin fin en ambos sentidos | $\\overleftrightarrow{AB}$ |\n| **Segmento AB** | La parte de la recta entre A y B | $\\overline{AB}$ |\n| **Rayo AB** | Empieza en A y se extiende sin fin pasando por B | $\\overrightarrow{AB}$ |\n\nEl segmento AB es el **camino más corto** entre A y B, y su longitud es la **distancia** entre esos puntos.\n\nUn **plano** se forma con **tres puntos que no estén en la misma recta**.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Punto, recta, segmento y rayo\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuántas rectas pasan por dos puntos distintos A y B?\nopciones:\n- [x] Solo una\n- [ ] Dos\n- [ ] Muchas\nmezclar: no\nexplicacion: Por dos puntos pasa una sola recta.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se llama la parte de una recta que está entre los puntos A y B?\nopciones:\n- [x] Segmento AB\n- [ ] Rayo AB\n- [ ] Recta AB\n- [ ] Plano AB\nexplicacion: El segmento AB es la parte delimitada por A y B.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se llama la línea que empieza en el punto A y se extiende sin fin pasando por B?\nopciones:\n- [x] Rayo AB\n- [ ] Segmento AB\n- [ ] Recta AB\nexplicacion: El rayo tiene un punto de inicio y se extiende infinitamente en un sentido.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuántos puntos no alineados se necesitan, como mínimo, para formar un plano?\nrespuesta: 3\nexplicacion: Un plano se forma con tres puntos que no estén en la misma recta.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.2: Clasificación de ángulos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Clasificación de ángulos', 'Un **ángulo** es la abertura entre dos rayos (sus **lados**) que salen del mismo punto (el **vértice**). Se mide en grados (°) con un transportador.\n\n| Tipo | Medida |\n|---|---|\n| **Agudo** | Mayor que 0° y menor que 90° |\n| **Recto** | Exactamente 90° |\n| **Obtuso** | Mayor que 90° y menor que 180° |\n| **Llano** | 180° (media vuelta) |\n| **Completo** | 360° (una vuelta) |\n\n**Ejemplos:** 45° es agudo, 90° es recto y 150° es obtuso.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Clasificación de ángulos\n\n```pregunta\ntipo: opcion\nvariables: a = 10..89\nenunciado: Un ángulo que mide [[a]]° es…\nopciones:\n- [x] Agudo\n- [ ] Recto\n- [ ] Obtuso\n- [ ] Llano\nmezclar: no\nexplicacion: [[a]]° es menor que 90°, por eso es agudo.\n```\n\n```pregunta\ntipo: opcion\nvariables: a = 91..179\nenunciado: Un ángulo que mide [[a]]° es…\nopciones:\n- [ ] Agudo\n- [ ] Recto\n- [x] Obtuso\n- [ ] Llano\nmezclar: no\nexplicacion: [[a]]° está entre 90° y 180°, por eso es obtuso.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Un ángulo que mide 90° es…\nopciones:\n- [ ] Agudo\n- [x] Recto\n- [ ] Obtuso\n- [ ] Llano\nmezclar: no\nexplicacion: Un ángulo de exactamente 90° es recto.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuántos grados mide un ángulo llano?\nrespuesta: 180\nexplicacion: El ángulo llano es media vuelta: 180°.\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuántos grados mide un ángulo completo?\nrespuesta: 360\nexplicacion: El ángulo completo es una vuelta entera: 360°.\n```', FALSE, LAST_INSERT_ID());

-- Tema 2: Ángulos y bisectriz
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Ángulos y bisectriz', 20, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 2.1: Ángulos complementarios y suplementarios
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Ángulos complementarios y suplementarios', '- Dos ángulos son **complementarios** si suman **90°**: $\\angle a + \\angle b = 90°$\n- Dos ángulos son **suplementarios** si suman **180°**: $\\angle a + \\angle b = 180°$\n\n**Ejemplos:**\n\n- $54° + 36° = 90°$: son complementarios.\n- $57° + 123° = 180°$: son suplementarios.\n\n**Para encontrar el complemento** de un ángulo se resta de 90°: el complemento de 27° es $90° - 27° = 63°$.\n\n**Para encontrar el suplemento** se resta de 180°: el suplemento de 36° es $180° - 36° = 144°$.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Complementarios y suplementarios\n\n```pregunta\ntipo: numero\nvariables: b = 10..80\nenunciado: $\\angle A$ es complementario de $\\angle B$ y $\\angle B = [[b]]°$. ¿Cuánto mide $\\angle A$? (en grados)\nrespuesta: 90 - b\nexplicacion: $90° - [[b]]° = [[90-b]]°$\n```\n\n```pregunta\ntipo: numero\nvariables: b = 10..170\nenunciado: $\\angle A$ es suplementario de $\\angle B$ y $\\angle B = [[b]]°$. ¿Cuánto mide $\\angle A$? (en grados)\nrespuesta: 180 - b\nexplicacion: $180° - [[b]]° = [[180-b]]°$\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál pareja de ángulos es **complementaria**?\nopciones:\n- [x] 52° y 38°\n- [ ] 52° y 48°\n- [ ] 42° y 38°\n- [ ] 48° y 52°\nexplicacion: $52° + 38° = 90°$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál pareja de ángulos es **suplementaria**?\nopciones:\n- [x] 64° y 116°\n- [ ] 64° y 104°\n- [ ] 76° y 116°\n- [ ] 76° y 14°\nexplicacion: $64° + 116° = 180°$.\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.2: Bisectriz de un ángulo
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Bisectriz de un ángulo', 'Si un rayo $OP$ divide al $\\angle AOB$ en $\\angle AOP = 40°$ y $\\angle BOP = 20°$, las dos partes son diferentes. Pero si un rayo $OQ$ lo divide en $30°$ y $30°$, las dos partes son **iguales**.\n\nAl rayo que divide un ángulo en **dos partes iguales** se le llama **bisectriz** del ángulo.\n\n$$\\text{Cada parte} = \\frac{\\angle AOB}{2}$$\n\n**Ejemplo:** si $\\angle AOB = 70°$, la bisectriz lo divide en dos ángulos de $35°$.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Bisectriz\n\n```pregunta\ntipo: numero\nvariables: m = 10..85\nenunciado: $\\angle AOB = [[2*m]]°$ y $OQ$ es su bisectriz. ¿Cuánto mide $\\angle AOQ$? (en grados)\nrespuesta: m\nexplicacion: La bisectriz divide el ángulo a la mitad: $[[2*m]]° \\div 2 = [[m]]°$\n```\n\n```pregunta\ntipo: numero\nenunciado: $OQ$ es la bisectriz de $\\angle AOB$ y $\\angle AOQ = 30°$. ¿Cuánto mide $\\angle AOB$? (en grados)\nrespuesta: 60\nexplicacion: Las dos partes son iguales: $30° + 30° = 60°$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Un rayo divide al $\\angle AOB$ en dos ángulos. ¿En cuál caso el rayo es la **bisectriz**?\nopciones:\n- [x] 45° y 45°\n- [ ] 55° y 25°\n- [ ] 10° y 45°\n- [ ] 30° y 60°\nexplicacion: Es bisectriz solo cuando las dos partes miden lo mismo.\n```', FALSE, LAST_INSERT_ID());

-- Tema 3: Cuadriláteros
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Cuadriláteros', 30, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 3.1: Perímetro de cuadriláteros
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Perímetro de cuadriláteros', 'El **perímetro** es la suma de las longitudes de todos los lados de una figura.\n\nEn un cuadrilátero de lados $a$, $b$, $c$ y $d$:\n\n$$P = a + b + c + d$$\n\n**Ejemplo:** un cuadrilátero con lados de 3 cm, 2 cm, 4 cm y 5 cm tiene\n\n$$P = 3 + 2 + 4 + 5 = 14 \\text{ cm}$$\n\n> **Atajos:** en un cuadrado de lado $l$, $P = 4 \\times l$. En un rectángulo, $P = 2 \\times (\\text{base} + \\text{altura})$.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Perímetro\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9, c = 2..9, d = 2..9\nenunciado: Un cuadrilátero tiene lados de [[a]] cm, [[b]] cm, [[c]] cm y [[d]] cm. ¿Cuál es su perímetro? (en cm)\nrespuesta: a + b + c + d\nexplicacion: $[[a]] + [[b]] + [[c]] + [[d]] = [[a+b+c+d]]$ cm\n```\n\n```pregunta\ntipo: numero\nvariables: l = 2..12\nenunciado: ¿Cuál es el perímetro de un cuadrado de [[l]] cm de lado? (en cm)\nrespuesta: 4 * l\nexplicacion: $4 \\times [[l]] = [[4*l]]$ cm\n```\n\n```pregunta\ntipo: numero\nvariables: b = 3..12, h = 2..9\nenunciado: ¿Cuál es el perímetro de un rectángulo de [[b]] cm de base y [[h]] cm de altura? (en cm)\nrespuesta: 2 * (b + h)\nexplicacion: $2 \\times ([[b]] + [[h]]) = [[2*(b+h)]]$ cm\n```\n\n```pregunta\ntipo: numero\nenunciado: Un cuadrilátero tiene lados de 7 cm, 4 cm, 5 cm y 6 cm. ¿Cuál es su perímetro? (en cm)\nrespuesta: 22\nexplicacion: $7 + 4 + 5 + 6 = 22$ cm\n```', FALSE, LAST_INSERT_ID());

-- Lección 3.2: Área de rectángulos y cuadrados
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Área de rectángulos y cuadrados', 'El **área** mide cuánto espacio ocupa una figura. Se expresa en unidades cuadradas, como cm².\n\nUn rectángulo de 6 cm de base y 3 cm de altura se puede llenar con $6 \\times 3 = 18$ cuadritos de 1 cm². Su área es 18 cm².\n\n$$\\text{Área del rectángulo} = \\text{base} \\times \\text{altura}$$\n\nComo el cuadrado tiene sus cuatro lados iguales:\n\n$$\\text{Área del cuadrado} = \\text{lado} \\times \\text{lado}$$', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Área de rectángulos y cuadrados\n\n```pregunta\ntipo: numero\nvariables: b = 3..15, h = 2..10\nenunciado: ¿Cuál es el área de un rectángulo de [[b]] cm de base y [[h]] cm de altura? (en cm²)\nrespuesta: b * h\nexplicacion: $[[b]] \\times [[h]] = [[b*h]]$ cm²\n```\n\n```pregunta\ntipo: numero\nvariables: l = 2..12\nenunciado: ¿Cuál es el área de un cuadrado de [[l]] cm de lado? (en cm²)\nrespuesta: l * l\nexplicacion: $[[l]] \\times [[l]] = [[l*l]]$ cm²\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es el área de un rectángulo de 12 cm de base y 5 cm de altura? (en cm²)\nrespuesta: 60\nexplicacion: $12 \\times 5 = 60$ cm²\n```\n\n```pregunta\ntipo: numero\nenunciado: Un rectángulo tiene un área de 36 cm² y una base de 9 cm. ¿Cuánto mide su altura? (en cm)\nrespuesta: 4\nexplicacion: $\\text{altura} = 36 \\div 9 = 4$ cm\n```', FALSE, LAST_INSERT_ID());

-- Lección 3.3: Área de paralelogramos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Área de paralelogramos', 'Un **paralelogramo** se puede transformar en un rectángulo: se corta un triángulo de un lado y se pega en el otro. El área no cambia.\n\n$$\\text{Área del paralelogramo} = \\text{base} \\times \\text{altura}$$\n\nLa **altura** es el segmento **perpendicular** a la base (forma un ángulo recto con ella), no el lado inclinado.\n\n**Ejemplo:** base 4 cm y altura 3 cm: $4 \\times 3 = 12$ cm².', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Área de paralelogramos\n\n```pregunta\ntipo: numero\nvariables: b = 3..15, h = 2..10\nenunciado: ¿Cuál es el área de un paralelogramo de [[b]] cm de base y [[h]] cm de altura? (en cm²)\nrespuesta: b * h\nexplicacion: $[[b]] \\times [[h]] = [[b*h]]$ cm²\n```\n\n```pregunta\ntipo: numero\nenunciado: Un paralelogramo tiene 10 cm de base, 7 cm de altura y su lado inclinado mide 8 cm. ¿Cuál es su área? (en cm²)\nrespuesta: 70\nexplicacion: Se usa la altura, no el lado inclinado: $10 \\times 7 = 70$ cm².\n```\n\n```pregunta\ntipo: opcion\nenunciado: Para calcular el área de un paralelogramo, ¿qué medida se usa como altura?\nopciones:\n- [x] El segmento perpendicular a la base\n- [ ] El lado inclinado\n- [ ] La suma de los dos lados\nexplicacion: La altura siempre es perpendicular a la base.\n```', FALSE, LAST_INSERT_ID());

-- Lección 3.4: Área de trapecios
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Área de trapecios', 'Un **trapecio** tiene dos lados paralelos: la **base mayor** y la **base menor**. La **altura** es la distancia perpendicular entre ellas.\n\nDos trapecios iguales forman un paralelogramo de base (base mayor + base menor). Por eso, el área de un trapecio es la mitad:\n\n$$\\text{Área del trapecio} = \\frac{(\\text{base mayor} + \\text{base menor}) \\times \\text{altura}}{2}$$\n\n**Ejemplo:** base mayor 5 cm, base menor 2 cm y altura 4 cm:\n\n$$\\frac{(5 + 2) \\times 4}{2} = \\frac{28}{2} = 14 \\text{ cm}^2$$', 40, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Área de trapecios\n\n```pregunta\ntipo: numero\nvariables: B = 6..12, b = 2..5, h = 2|4|6|8\nenunciado: Un trapecio tiene base mayor de [[B]] cm, base menor de [[b]] cm y altura de [[h]] cm. ¿Cuál es su área? (en cm²)\nrespuesta: (B + b) * h / 2\nexplicacion: $\\frac{([[B]] + [[b]]) \\times [[h]]}{2} = \\frac{[[(B+b)*h]]}{2} = [[(B+b)*h/2]]$ cm²\n```\n\n```pregunta\ntipo: numero\nenunciado: Un trapecio tiene base mayor de 8 cm, base menor de 3 cm y altura de 6 cm. ¿Cuál es su área? (en cm²)\nrespuesta: 33\nexplicacion: $\\frac{(8 + 3) \\times 6}{2} = \\frac{66}{2} = 33$ cm²\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es la fórmula del área de un trapecio?\nopciones:\n- [x] $\\frac{(\\text{base mayor} + \\text{base menor}) \\times \\text{altura}}{2}$\n- [ ] $\\text{base mayor} \\times \\text{base menor}$\n- [ ] $(\\text{base mayor} + \\text{base menor}) \\times \\text{altura}$\nexplicacion: Se suman las bases, se multiplica por la altura y se divide entre 2.\n```', FALSE, LAST_INSERT_ID());

-- Tema 4: Triángulos
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Triángulos', 40, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 4.1: Clasificación de triángulos por sus ángulos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Clasificación de triángulos por sus ángulos', 'Según la medida de sus ángulos internos, un triángulo puede ser:\n\n| Tipo | Característica | Ejemplo |\n|---|---|---|\n| **Acutángulo** | Sus tres ángulos miden menos de 90° | 60°, 80°, 40° |\n| **Rectángulo** | Tiene un ángulo de 90° | 40°, 90°, 50° |\n| **Obtusángulo** | Tiene un ángulo mayor que 90° | 30°, 50°, 100° |\n\n> Los triángulos **equiláteros** (tres lados iguales, cada ángulo de 60°) son acutángulos.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Clasificación por ángulos\n\n```pregunta\ntipo: opcion\nenunciado: Un triángulo tiene ángulos de 30°, 50° y 100°. ¿Qué tipo de triángulo es?\nopciones:\n- [ ] Acutángulo\n- [ ] Rectángulo\n- [x] Obtusángulo\nmezclar: no\nexplicacion: Tiene un ángulo mayor que 90° (100°).\n```\n\n```pregunta\ntipo: opcion\nenunciado: Un triángulo tiene ángulos de 60°, 80° y 40°. ¿Qué tipo de triángulo es?\nopciones:\n- [x] Acutángulo\n- [ ] Rectángulo\n- [ ] Obtusángulo\nmezclar: no\nexplicacion: Los tres ángulos son menores que 90°.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Un triángulo tiene ángulos de 45°, 90° y 45°. ¿Qué tipo de triángulo es?\nopciones:\n- [ ] Acutángulo\n- [x] Rectángulo\n- [ ] Obtusángulo\nmezclar: no\nexplicacion: Tiene un ángulo de 90°.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Un triángulo equilátero es…\nopciones:\n- [x] Acutángulo\n- [ ] Rectángulo\n- [ ] Obtusángulo\nmezclar: no\nexplicacion: Sus tres ángulos miden 60°, todos menores que 90°.\n```', FALSE, LAST_INSERT_ID());

-- Lección 4.2: Ángulos internos y externos de un triángulo
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Ángulos internos y externos de un triángulo', 'Los tres ángulos que se forman **dentro** de un triángulo son sus **ángulos internos**, y siempre suman 180°:\n\n$$\\angle a + \\angle b + \\angle c = 180°$$\n\nSi se prolonga un lado, se forma un **ángulo externo** $\\angle d$ junto a $\\angle c$. Como juntos forman un ángulo llano, $\\angle c + \\angle d = 180°$. Por eso:\n\n$$\\angle d = \\angle a + \\angle b$$\n\n**El ángulo externo es igual a la suma de los dos ángulos internos que no están junto a él.**\n\n**Ejemplo:** si $\\angle a = 50°$ y $\\angle b = 60°$, entonces $\\angle c = 70°$ y el ángulo externo $\\angle d = 110°$.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Ángulos internos y externos\n\n```pregunta\ntipo: numero\nvariables: a = 30..80, b = 20..70\nenunciado: Dos ángulos internos de un triángulo miden [[a]]° y [[b]]°. ¿Cuánto mide el tercer ángulo? (en grados)\nrespuesta: 180 - a - b\nexplicacion: $180° - [[a]]° - [[b]]° = [[180-a-b]]°$\n```\n\n```pregunta\ntipo: numero\nvariables: a = 30..80, b = 20..70\nenunciado: Dos ángulos internos de un triángulo miden [[a]]° y [[b]]°. ¿Cuánto mide el ángulo externo junto al tercer ángulo? (en grados)\nrespuesta: a + b\nexplicacion: El ángulo externo es la suma de los dos internos no adyacentes: $[[a]]° + [[b]]° = [[a+b]]°$\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuánto suman los tres ángulos internos de cualquier triángulo? (en grados)\nrespuesta: 180\nexplicacion: La suma de los ángulos internos de un triángulo siempre es 180°.\n```\n\n```pregunta\ntipo: numero\nvariables: c = 40..140\nenunciado: Un ángulo interno de un triángulo mide [[c]]°. ¿Cuánto mide el ángulo externo que está junto a él? (en grados)\nrespuesta: 180 - c\nexplicacion: Juntos forman un ángulo llano: $180° - [[c]]° = [[180-c]]°$\n```', FALSE, LAST_INSERT_ID());

-- Lección 4.3: Área de triángulos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Área de triángulos', 'Dos triángulos iguales forman un paralelogramo. Por eso, el área de un triángulo es la **mitad** del área del paralelogramo:\n\n$$\\text{Área del triángulo} = \\frac{\\text{base} \\times \\text{altura}}{2}$$\n\n**Ejemplo:** base 4 cm y altura 3 cm:\n\n$$\\frac{4 \\times 3}{2} = \\frac{12}{2} = 6 \\text{ cm}^2$$\n\n> **Recuerda:** la altura es perpendicular a la base.', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Área de triángulos\n\n```pregunta\ntipo: numero\nvariables: b = 2|4|6|8|10|12, h = 3..9\nenunciado: ¿Cuál es el área de un triángulo de [[b]] cm de base y [[h]] cm de altura? (en cm²)\nrespuesta: b * h / 2\nexplicacion: $\\frac{[[b]] \\times [[h]]}{2} = \\frac{[[b*h]]}{2} = [[b*h/2]]$ cm²\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es el área de un triángulo de 10 cm de base y 6 cm de altura? (en cm²)\nrespuesta: 30\nexplicacion: $\\frac{10 \\times 6}{2} = 30$ cm²\n```\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es el área de un triángulo de 3 cm de base y 4 cm de altura? (en cm²)\nrespuesta: 6\nexplicacion: $\\frac{3 \\times 4}{2} = 6$ cm²\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es la fórmula del área de un triángulo?\nopciones:\n- [x] $\\frac{\\text{base} \\times \\text{altura}}{2}$\n- [ ] $\\text{base} \\times \\text{altura}$\n- [ ] $\\text{base} + \\text{altura}$\nexplicacion: El triángulo es la mitad de un paralelogramo con la misma base y altura.\n```', FALSE, LAST_INSERT_ID());

COMMIT;

SELECT p.Plan_Id, p.Plan_Nombre, COUNT(DISTINCT t.Tema_Id) AS Temas, COUNT(DISTINCT l.Leccion_Id) AS Lecciones, COUNT(e.Ejercicio_Id) AS Ejercicios
FROM Planes_Estudio p JOIN Temas t ON t.Plan_Id = p.Plan_Id JOIN Lecciones l ON l.Tema_Id = t.Tema_Id
LEFT JOIN Ejercicios e ON e.Leccion_Id = l.Leccion_Id WHERE p.Plan_Id = @plan_id GROUP BY p.Plan_Id, p.Plan_Nombre;
